import{_ as e,o as d,c as o,a2 as c}from"./chunks/framework.LX5S0jbT.js";const u=JSON.parse('{"title":"Keybindings Reference","description":"","frontmatter":{},"headers":[],"relativePath":"keybindings.md","filePath":"keybindings.md"}'),r={name:"keybindings.md"};function a(i,t,n,s,l,p){return d(),o("div",null,[...t[0]||(t[0]=[c(`<h1 id="keybindings-reference" tabindex="-1">Keybindings Reference <a class="header-anchor" href="#keybindings-reference" aria-label="Permalink to &quot;Keybindings Reference&quot;">​</a></h1><p>Pi exposes named actions, such as <code>app.session.new</code>, that can be assigned keybindings. You can change default assignments or bind unassigned actions in Pi&#39;s <a href="./configuration.html#agent-directory">user configuration</a>.</p><p>Run <code>/hotkeys</code> to see the active shortcuts for the main editor and application.</p><h2 id="assign-keybindings" tabindex="-1">Assign keybindings <a class="header-anchor" href="#assign-keybindings" aria-label="Permalink to &quot;Assign keybindings&quot;">​</a></h2><p>Create <code>&lt;agent-dir&gt;/keybindings.json</code>. The agent directory defaults to <code>~/.pi/agent</code> and is described in <a href="./configuration.html#agent-directory">Agent directory</a>.</p><p>Map each action identifier to one key or a list of keys:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;$schema&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://pi.dev/schemas/keybindings.schema.json&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;app.session.new&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ctrl+shift+n&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;app.session.tree&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ctrl+shift+t&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;alt+shift+t&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>A configured value replaces the default for that action. Use an empty list to disable an action&#39;s keybindings:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;tui.altScreen.pageUp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: []</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>After editing the file, run <code>/reload</code> to apply the changes to the active session.</p><h2 id="key-syntax" tabindex="-1">Key syntax <a class="header-anchor" href="#key-syntax" aria-label="Permalink to &quot;Key syntax&quot;">​</a></h2><p>Write a key as <code>modifier+key</code>. Modifiers are <code>ctrl</code>, <code>shift</code>, <code>alt</code>, and <code>super</code>. You can combine modifiers. Valid keys are:</p><ul><li><strong>Letters:</strong> <code>a-z</code></li><li><strong>Digits:</strong> <code>0-9</code></li><li><strong>Special:</strong> <code>escape</code>, <code>esc</code>, <code>enter</code>, <code>return</code>, <code>tab</code>, <code>space</code>, <code>backspace</code>, <code>delete</code>, <code>insert</code>, <code>clear</code>, <code>home</code>, <code>end</code>, <code>pageUp</code>, <code>pageDown</code>, <code>up</code>, <code>down</code>, <code>left</code>, <code>right</code></li><li><strong>Function:</strong> <code>f1</code>-<code>f12</code></li><li><strong>Symbols:</strong> <code>\`</code>, <code>-</code>, <code>=</code>, <code>[</code>, <code>]</code>, <code>\\</code>, <code>;</code>, <code>&#39;</code>, <code>,</code>, <code>.</code>, <code>/</code>, <code>!</code>, <code>@</code>, <code>#</code>, <code>$</code>, <code>%</code>, <code>^</code>, <code>&amp;</code>, <code>*</code>, <code>(</code>, <code>)</code>, <code>_</code>, <code>+</code>, <code>|</code>, <code>~</code>, <code>{</code>, <code>}</code>, <code>:</code>, <code>&lt;</code>, <code>&gt;</code>, <code>?</code></li></ul><p>Examples: <code>ctrl+shift+x</code>, <code>alt+ctrl+x</code>, <code>ctrl+shift+alt+x</code>, <code>super+k</code>, <code>ctrl+super+k</code>, and <code>ctrl+1</code>.</p><p><code>super</code> bindings require a terminal that reports the modifier separately, typically through the Kitty keyboard protocol. They may not work in terminals without that support.</p><h2 id="actions" tabindex="-1">Actions <a class="header-anchor" href="#actions" aria-label="Permalink to &quot;Actions&quot;">​</a></h2><h3 id="terminal-ui" tabindex="-1">Terminal UI <a class="header-anchor" href="#terminal-ui" aria-label="Permalink to &quot;Terminal UI&quot;">​</a></h3><h4 id="cursor-movement" tabindex="-1">Cursor movement <a class="header-anchor" href="#cursor-movement" aria-label="Permalink to &quot;Cursor movement&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Keybinding id</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>tui.editor.cursorUp</code></td><td><code>up</code></td><td>Move cursor up, browsing older history at the top</td></tr><tr><td><code>tui.editor.cursorDown</code></td><td><code>down</code></td><td>Move cursor down, browsing newer history at the bottom</td></tr><tr><td><code>tui.editor.historyPrevious</code></td><td>None</td><td>Select the previous prompt history entry</td></tr><tr><td><code>tui.editor.historyNext</code></td><td>None</td><td>Select the next prompt history entry</td></tr><tr><td><code>tui.editor.cursorLeft</code></td><td><code>left</code>, <code>ctrl+b</code></td><td>Move cursor left</td></tr><tr><td><code>tui.editor.cursorRight</code></td><td><code>right</code>, <code>ctrl+f</code></td><td>Move cursor right</td></tr><tr><td><code>tui.editor.cursorWordLeft</code></td><td><code>alt+left</code>, <code>ctrl+left</code>, <code>alt+b</code></td><td>Move cursor word left</td></tr><tr><td><code>tui.editor.cursorWordRight</code></td><td><code>alt+right</code>, <code>ctrl+right</code>, <code>alt+f</code></td><td>Move cursor word right</td></tr><tr><td><code>tui.editor.cursorLineStart</code></td><td><code>home</code>, <code>ctrl+a</code></td><td>Move to line start</td></tr><tr><td><code>tui.editor.cursorLineEnd</code></td><td><code>end</code>, <code>ctrl+e</code></td><td>Move to line end</td></tr><tr><td><code>tui.editor.jumpForward</code></td><td><code>ctrl+]</code></td><td>Jump forward to character</td></tr><tr><td><code>tui.editor.jumpBackward</code></td><td><code>ctrl+alt+]</code></td><td>Jump backward to character</td></tr><tr><td><code>tui.editor.pageUp</code></td><td><code>pageUp</code>, <code>ctrl+pageUp</code></td><td>Scroll up by page</td></tr><tr><td><code>tui.editor.pageDown</code></td><td><code>pageDown</code>, <code>ctrl+pageDown</code></td><td>Scroll down by page</td></tr></tbody></table><p>The dedicated history actions browse prompt history regardless of cursor position and take precedence over application actions using the same key.</p><h4 id="text-editing" tabindex="-1">Text editing <a class="header-anchor" href="#text-editing" aria-label="Permalink to &quot;Text editing&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Keybinding id</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>tui.editor.deleteCharBackward</code></td><td><code>backspace</code></td><td>Delete character backward</td></tr><tr><td><code>tui.editor.deleteCharForward</code></td><td><code>delete</code>, <code>ctrl+d</code></td><td>Delete character forward</td></tr><tr><td><code>tui.editor.deleteWordBackward</code></td><td><code>ctrl+w</code>, <code>alt+backspace</code></td><td>Delete word backward</td></tr><tr><td><code>tui.editor.deleteWordForward</code></td><td><code>alt+d</code>, <code>alt+delete</code></td><td>Delete word forward</td></tr><tr><td><code>tui.editor.deleteToLineStart</code></td><td><code>ctrl+u</code></td><td>Delete to line start</td></tr><tr><td><code>tui.editor.deleteToLineEnd</code></td><td><code>ctrl+k</code></td><td>Delete to line end</td></tr><tr><td><code>tui.editor.yank</code></td><td><code>ctrl+y</code></td><td>Paste most recently deleted text</td></tr><tr><td><code>tui.editor.yankPop</code></td><td><code>alt+y</code></td><td>Cycle through deleted text after yank</td></tr><tr><td><code>tui.editor.undo</code></td><td><code>ctrl+-</code> (<code>ctrl+z</code> on Windows; <code>alt+z</code> on WSL)</td><td>Undo last edit</td></tr></tbody></table><h4 id="input-and-selection" tabindex="-1">Input and selection <a class="header-anchor" href="#input-and-selection" aria-label="Permalink to &quot;Input and selection&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Keybinding id</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>tui.input.newLine</code></td><td><code>shift+enter</code>, <code>ctrl+j</code></td><td>Insert new line</td></tr><tr><td><code>tui.input.submit</code></td><td><code>enter</code></td><td>Submit input</td></tr><tr><td><code>tui.input.tab</code></td><td><code>tab</code></td><td>Tab or autocomplete</td></tr><tr><td><code>tui.input.copy</code></td><td><code>ctrl+c</code></td><td>Copy selection</td></tr><tr><td><code>tui.select.up</code></td><td><code>up</code></td><td>Move selection up</td></tr><tr><td><code>tui.select.down</code></td><td><code>down</code></td><td>Move selection down</td></tr><tr><td><code>tui.select.pageUp</code></td><td><code>pageUp</code></td><td>Page up in list</td></tr><tr><td><code>tui.select.pageDown</code></td><td><code>pageDown</code></td><td>Page down in list</td></tr><tr><td><code>tui.select.confirm</code></td><td><code>enter</code></td><td>Confirm selection</td></tr><tr><td><code>tui.select.cancel</code></td><td><code>escape</code>, <code>ctrl+c</code></td><td>Cancel selection</td></tr></tbody></table><h4 id="fullscreen" tabindex="-1">Fullscreen <a class="header-anchor" href="#fullscreen" aria-label="Permalink to &quot;Fullscreen&quot;">​</a></h4><p>In fullscreen mode, these actions control the transcript and take precedence over editor actions using the same key.</p><table tabindex="0"><thead><tr><th>Keybinding id</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>tui.altScreen.pageUp</code></td><td><code>pageUp</code></td><td>Scroll the transcript up by one page</td></tr><tr><td><code>tui.altScreen.pageDown</code></td><td><code>pageDown</code></td><td>Scroll the transcript down by one page</td></tr><tr><td><code>tui.altScreen.halfPageUp</code></td><td>None</td><td>Scroll the transcript up by half a page</td></tr><tr><td><code>tui.altScreen.halfPageDown</code></td><td>None</td><td>Scroll the transcript down by half a page</td></tr><tr><td><code>tui.altScreen.lineUp</code></td><td>None</td><td>Scroll the transcript up by one line</td></tr><tr><td><code>tui.altScreen.lineDown</code></td><td>None</td><td>Scroll the transcript down by one line</td></tr><tr><td><code>tui.altScreen.previousPrompt</code></td><td><code>ctrl+shift+up</code>, <code>ctrl+up</code> (<code>ctrl+up</code> only on Windows and WSL)</td><td>Jump to the previous marked message</td></tr><tr><td><code>tui.altScreen.nextPrompt</code></td><td><code>ctrl+shift+down</code>, <code>ctrl+down</code> (<code>ctrl+down</code> only on Windows and WSL)</td><td>Jump to the next marked message</td></tr><tr><td><code>tui.altScreen.search</code></td><td><code>ctrl+shift+f</code> (<code>ctrl+f</code> on Windows and WSL)</td><td>Search the rendered transcript</td></tr><tr><td><code>tui.altScreen.searchNext</code></td><td><code>enter</code>, <code>ctrl+g</code></td><td>Select the next search match while searching</td></tr><tr><td><code>tui.altScreen.searchPrevious</code></td><td><code>shift+enter</code>, <code>ctrl+shift+g</code></td><td>Select the previous search match while searching</td></tr><tr><td><code>tui.altScreen.searchClose</code></td><td><code>escape</code></td><td>Close transcript search</td></tr><tr><td><code>tui.altScreen.top</code></td><td><code>ctrl+home</code></td><td>Scroll to the beginning of the transcript</td></tr><tr><td><code>tui.altScreen.bottom</code></td><td><code>ctrl+end</code></td><td>Scroll to the transcript end and follow new output</td></tr></tbody></table><h3 id="application" tabindex="-1">Application <a class="header-anchor" href="#application" aria-label="Permalink to &quot;Application&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Keybinding id</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>app.interrupt</code></td><td><code>escape</code></td><td>Cancel / abort</td></tr><tr><td><code>app.clear</code></td><td><code>ctrl+c</code></td><td>Clear editor (first) / exit (second)</td></tr><tr><td><code>app.exit</code></td><td><code>ctrl+d</code></td><td>Exit (when editor empty)</td></tr><tr><td><code>app.suspend</code></td><td><code>ctrl+z</code> (None on Windows)</td><td>Suspend to background</td></tr><tr><td><code>app.editor.external</code></td><td><code>ctrl+g</code></td><td>Open in external editor (<code>externalEditor</code>, <code>$VISUAL</code>, <code>$EDITOR</code>, Notepad on Windows, or <code>nano</code> elsewhere)</td></tr><tr><td><code>app.clipboard.pasteImage</code></td><td><code>ctrl+v</code> (<code>alt+v</code> on Windows and WSL)</td><td>Paste files on macOS, images, or text from clipboard</td></tr></tbody></table><p>On native Windows, <code>app.suspend</code> has no default because Windows terminals do not support Unix job control. If you assign it manually, Pi shows a status message instead of suspending. WSL uses the normal <code>ctrl+z</code> and <code>fg</code> behavior.</p><h3 id="sessions" tabindex="-1">Sessions <a class="header-anchor" href="#sessions" aria-label="Permalink to &quot;Sessions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Keybinding id</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>app.session.new</code></td><td>None</td><td>Start a new session (<code>/new</code>)</td></tr><tr><td><code>app.session.tree</code></td><td>None</td><td>Open session tree navigator (<code>/tree</code>)</td></tr><tr><td><code>app.session.fork</code></td><td>None</td><td>Fork current session (<code>/fork</code>)</td></tr><tr><td><code>app.session.resume</code></td><td>None</td><td>Open session resume picker (<code>/resume</code>)</td></tr><tr><td><code>app.session.togglePath</code></td><td><code>ctrl+p</code></td><td>Toggle path display</td></tr><tr><td><code>app.session.toggleSort</code></td><td><code>ctrl+s</code></td><td>Toggle sort mode</td></tr><tr><td><code>app.session.toggleNamedFilter</code></td><td><code>ctrl+n</code></td><td>Toggle named-only filter</td></tr><tr><td><code>app.session.rename</code></td><td><code>ctrl+r</code></td><td>Rename session</td></tr><tr><td><code>app.session.delete</code></td><td><code>ctrl+d</code></td><td>Delete session</td></tr><tr><td><code>app.session.deleteNoninvasive</code></td><td><code>ctrl+backspace</code></td><td>Delete session when query is empty</td></tr></tbody></table><h3 id="models-and-thinking" tabindex="-1">Models and Thinking <a class="header-anchor" href="#models-and-thinking" aria-label="Permalink to &quot;Models and Thinking&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Keybinding id</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>app.model.select</code></td><td><code>ctrl+l</code></td><td>Open model selector</td></tr><tr><td><code>app.model.cycleForward</code></td><td><code>ctrl+p</code></td><td>Cycle to next model</td></tr><tr><td><code>app.model.cycleBackward</code></td><td><code>shift+ctrl+p</code> (<code>alt+p</code> on Windows and WSL)</td><td>Cycle to previous model</td></tr><tr><td><code>app.models.save</code></td><td><code>ctrl+s</code></td><td>Save the selected default model or scoped model configuration to settings</td></tr><tr><td><code>app.thinking.cycle</code></td><td><code>shift+tab</code></td><td>Cycle thinking level</td></tr><tr><td><code>app.thinking.save</code></td><td><code>ctrl+s</code></td><td>Save current thinking level to settings</td></tr><tr><td><code>app.thinking.toggle</code></td><td><code>ctrl+t</code></td><td>Collapse or expand thinking blocks</td></tr></tbody></table><h3 id="display-and-message-queue" tabindex="-1">Display and Message Queue <a class="header-anchor" href="#display-and-message-queue" aria-label="Permalink to &quot;Display and Message Queue&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Keybinding id</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>app.tools.expand</code></td><td><code>ctrl+o</code></td><td>Collapse or expand tool output</td></tr><tr><td><code>app.message.copy</code></td><td><code>ctrl+x</code></td><td>Copy the selected message in <code>/tree</code>; in fullscreen mode, copy the active selection when <code>fullscreenCopyOnSelect</code> is <code>false</code>; otherwise copy the last assistant message. On OAuth sign-in screens, copy the sign-in URL</td></tr><tr><td><code>app.message.followUp</code></td><td><code>alt+enter</code> (<code>ctrl+q</code> on Windows and WSL)</td><td>Queue follow-up message</td></tr><tr><td><code>app.message.dequeue</code></td><td><code>alt+up</code> (<code>alt+q</code> on Windows and WSL)</td><td>Restore queued messages to editor</td></tr></tbody></table><h3 id="tree-navigation" tabindex="-1">Tree Navigation <a class="header-anchor" href="#tree-navigation" aria-label="Permalink to &quot;Tree Navigation&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Keybinding id</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>app.tree.foldOrUp</code></td><td><code>ctrl+left</code>, <code>alt+left</code></td><td>Fold current branch segment, or jump to the previous segment start</td></tr><tr><td><code>app.tree.unfoldOrDown</code></td><td><code>ctrl+right</code>, <code>alt+right</code></td><td>Unfold current branch segment, or jump to the next segment start or branch end</td></tr><tr><td><code>app.tree.editLabel</code></td><td><code>shift+l</code></td><td>Edit the label on the selected tree node</td></tr><tr><td><code>app.tree.toggleLabelTimestamp</code></td><td><code>shift+t</code></td><td>Toggle label timestamps in the tree</td></tr><tr><td><code>app.tree.filter.default</code></td><td><code>ctrl+d</code></td><td>Set tree filter to default view</td></tr><tr><td><code>app.tree.filter.noTools</code></td><td><code>ctrl+t</code></td><td>Toggle tree filter that hides tool results</td></tr><tr><td><code>app.tree.filter.userOnly</code></td><td><code>ctrl+u</code></td><td>Toggle tree filter that shows only user messages</td></tr><tr><td><code>app.tree.filter.labeledOnly</code></td><td><code>ctrl+l</code></td><td>Toggle tree filter that shows only labeled entries</td></tr><tr><td><code>app.tree.filter.all</code></td><td><code>ctrl+a</code></td><td>Toggle tree filter that shows all entries</td></tr><tr><td><code>app.tree.filter.cycleForward</code></td><td><code>ctrl+o</code></td><td>Cycle tree filter forward</td></tr><tr><td><code>app.tree.filter.cycleBackward</code></td><td><code>shift+ctrl+o</code></td><td>Cycle tree filter backward</td></tr></tbody></table><h3 id="scoped-models-selector" tabindex="-1">Scoped Models Selector <a class="header-anchor" href="#scoped-models-selector" aria-label="Permalink to &quot;Scoped Models Selector&quot;">​</a></h3><p>Used inside the scoped models selector (opened via <code>/scoped-models</code>).</p><table tabindex="0"><thead><tr><th>Keybinding id</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>app.models.enableAll</code></td><td><code>ctrl+a</code></td><td>Enable all models (or all matching the current search)</td></tr><tr><td><code>app.models.clearAll</code></td><td><code>ctrl+x</code></td><td>Clear all models (or all matching the current search)</td></tr><tr><td><code>app.models.toggleProvider</code></td><td><code>ctrl+p</code></td><td>Toggle all models for the current provider</td></tr><tr><td><code>app.models.reorderUp</code></td><td><code>alt+up</code></td><td>Move the selected model up in the cycle order</td></tr><tr><td><code>app.models.reorderDown</code></td><td><code>alt+down</code></td><td>Move the selected model down in the cycle order</td></tr></tbody></table>`,41)])])}const g=e(r,[["render",a]]);export{u as __pageData,g as default};
